const WIND_APPEARANCE_KEY='vento.wind-appearance';
function restoreWindAppearance(){try{const p=JSON.parse(window.localStorage?.getItem(WIND_APPEARANCE_KEY)||'{}');if(Number.isFinite(p.density))state.windDensity=windLayout(p.density).density;if(Number.isFinite(p.scale))state.windParticleScale=clamp(p.scale,.5,2.5);if(/^#[0-9a-f]{6}$/i.test(p.color))state.windColor=p.color.toLowerCase();}catch{}}
function saveWindAppearance(){try{window.localStorage?.setItem(WIND_APPEARANCE_KEY,JSON.stringify({scale:state.windParticleScale,color:state.windColor,density:state.windDensity}));}catch{}}
function syncWindAppearance(){const enabled=state.windVisible,box=$('#windAppearance');box.classList.toggle('hidden',!enabled);box.inert=!enabled;$('#windVisibility').setAttribute('aria-expanded',String(enabled));$('#windParticleSize').value=Math.round(state.windParticleScale*100);styleRange($('#windParticleSize'));$('#windParticleSizeOutput').textContent=`${Math.round(state.windParticleScale*100)}%`;const layout=windLayout(state.windDensity);$('#windDensity').value=Math.round(layout.density*100);styleRange($('#windDensity'));$('#windDensityOutput').textContent=`${layout.streams} flussi · ${layout.particles} particelle`;$('#windColor').value=state.windColor;$('#windColorOutput').textContent=state.windColor.toUpperCase();document.documentElement.style.setProperty('--wind-colour',state.windColor);}
restoreWindAppearance();
const windows=createWindowWorkspace();
const controlSpec=(c,k)=>rawControlSpec(c,k,state),controlToValue=(c,k,v)=>rawControlToValue(c,k,v,state),valueToControl=(c,k,v)=>rawValueToControl(c,k,v,state),formatControlValue=(c,k,v)=>rawFormatControlValue(c,k,v,state),controlPositionDescription=(c,k,v)=>rawControlDescription(c,k,v,state);
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let shapeComparison=null,autoCarTarget=null,autoLiveConstraintBlocked=false;
