function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function styleRange(el){el.style.setProperty('--value',`${(el.value-el.min)/(el.max-el.min)*100}%`);}
function controlFeedback(category,key){const def=CONTROL_DEFS[category]?.find(d=>d[0]===key);if(!def)return;$('#controlEffect').textContent=`${def[1]} · ${category==='genoa'&&key==='barber'&&!headsailInhaulAllowed(state)?'LP/J oltre 105%: barber solo sul carrello o verso l’esterno.':def[4]}`;if(category==='rig')$('#rigEffect').textContent=def[4];}
function syncControlInputs(category,key){const raw=state.controls[category][key],value=controlToValue(category,key,raw);$$(`[data-category="${category}"][data-key="${key}"]`).forEach(el=>{if(el!==document.activeElement||el.type==='range')el.value=value;el.setAttribute('aria-valuetext',controlPositionDescription(category,key,raw));if(el.type==='range')styleRange(el);});const out=$(`#out-${category}-${key}`);if(out)out.textContent=formatControlValue(category,key,raw);syncDirectControl();}
function applyControlValue(category,key,value,normalized=false){if(!controlEnabled(state,category,key))return;if(value===''||!Number.isFinite(Number(value)))return;const id=category+'.'+key,now=performance.now();if(!shapeComparison||shapeComparison.id!==id||now-shapeComparison.time>800)shapeComparison={id,time:now,before:Object.fromEntries(['main',state.foresail].filter(t=>t!=='none').map(t=>[t,shapeSummary(t,state)]))};shapeComparison.time=now;state.controls[category][key]=normalized?clamp(Number(value),0,100):valueToControl(category,key,Number(value));manual();updateImmediate();scene?.highlightAffected([`${category}.${key}`]);syncControlInputs(category,key);controlFeedback(category,key);}
function renderControlRows(category,target){
 const defs=CONTROL_DEFS[category].filter(d=>!(category==='genoa'&&d[0]==='battens'&&!hasHeadsailBattens(state)));
 target.innerHTML=defs.map(([key,name,lo,hi,help])=>{
  const p=controlSpec(category,key),value=controlToValue(category,key,state.controls[category][key]),id=`${category}.${key}`,enabled=controlEnabled(state,category,key),disabled=enabled?'':' disabled',colour=CONTROL_COLORS[id],effectiveHelp=p.outOnly?'LP/J oltre 105%: barber solo sul carrello o verso l’esterno.':help;
  return`<div class="control-row${enabled?'':' is-fixed'}" data-control-row="${id}"><label for="control-${category}-${key}"><span><i class="control-colour" style="background:${colour}"></i>${name}<span class="control-info" title="${effectiveHelp}" aria-hidden="true">i</span></span><output id="out-${category}-${key}" for="control-${category}-${key}">${formatControlValue(category,key,state.controls[category][key])}</output></label><button type="button" class="control-auto" data-auto-control="${id}" aria-label="Auto · ${name}" aria-describedby="singleAutoInfo" title="${singleAutoNote}">Auto</button><input id="control-${category}-${key}" type="range" min="${p.min}" max="${p.max}" step="${p.step}" value="${value}" data-category="${category}" data-key="${key}" aria-describedby="help-${category}-${key}"${disabled}><span class="sr-only" id="help-${category}-${key}">${effectiveHelp}</span><div class="control-ends" data-ends="${id}"><span>${p.low||lo}</span><span>${p.high||hi}</span></div>${p.centered?`<button class="barber-center" data-center-barber${disabled}>Centra sul carrello</button>${p.outOnly?'<p class="control-limit-note">LP/J oltre 105%: barber solo sul carrello o verso l’esterno.</p>':''}`:''}${p.position?`<label class="precise-position"><span>Posizione esatta</span><input id="number-${category}-${key}" type="number" min="${p.min}" max="${p.max}" step="${p.step}" value="${value.toFixed(3)}" data-category="${category}" data-key="${key}" inputmode="decimal" aria-label="${name}, posizione esatta in metri"${disabled}><span>m</span></label>`:''}<label class="control-enable"><input type="checkbox" data-control-enabled="${id}" aria-label="Regolabile · ${name}" title="Disattiva per fissare il valore corrente ed escludere la manovra da AUTO."${enabled?' checked':''}><span>${enabled?'Regolabile':'Fissa · esclusa da AUTO'}</span></label></div>`;
 }).join('');
 target.querySelectorAll('[data-auto-control]').forEach(b=>b.addEventListener('click',()=>autoSingleControl(b.dataset.autoControl)));syncSingleAutoButtons();
 target.querySelectorAll('[data-control-enabled]').forEach(el=>el.addEventListener('change',()=>changeControlEnabled(el.dataset.controlEnabled,el.checked)));
 target.querySelector('[data-center-barber]')?.addEventListener('click',()=>applyControlValue('genoa','barber',0));
 target.querySelectorAll('input[data-category]').forEach(el=>{if(el.type==='range')styleRange(el);el.addEventListener('input',()=>applyControlValue(category,el.dataset.key,el.value));if(el.type==='number')el.addEventListener('blur',()=>{const p=controlSpec(category,el.dataset.key);el.value=controlToValue(category,el.dataset.key,state.controls[category][el.dataset.key]).toFixed(p.position?3:0);});});
}

const singleAutoNote='Prende il valore dall’assetto ottimale complessivo per vento, vele e misure selezionate, non dall’ottimizzazione rispetto alle altre regolazioni attuali. Cambia solo questa manovra; le altre restano invariate e il rendimento attuale può rimanere inferiore. Le manovre fissate restano vincoli anche nel calcolo dell’assetto ottimale.';
function singleAutoAvailable(id){const [cat,key]=String(id||'').split('.');if(!controlEnabled(state,cat,key))return false;return cat==='rig'?(state.main||state.foresail!=='none'):cat==='main'?state.main:state.foresail===cat;}
function syncSingleAutoButtons(){$$('[data-auto-control]').forEach(b=>{const pending=singleAutoJob?.controlId===b.dataset.autoControl;b.disabled=!!singleAutoJob||!singleAutoAvailable(b.dataset.autoControl);b.setAttribute('aria-busy',String(pending));b.textContent=pending?'…':'Auto';const [cat,key]=b.dataset.autoControl.split('.');b.title=!controlEnabled(state,cat,key)?'Manovra fissa: riabilitala per usare AUTO.':singleAutoAvailable(b.dataset.autoControl)?singleAutoNote:'Issa questa vela per calcolare il valore ottimale.';});}
function cancelSingleAuto(){if(!singleAutoJob)return;singleAutoJob=null;++workerJob;solverWorker?.terminate();workerBusy=false;syncSingleAutoButtons();syncAuto();}
function autoSingleControl(controlId){
 if(!singleAutoAvailable(controlId))return;
 cancelSingleAuto();state.auto=false;autoCarTarget=null;clearTimeout(initialReferenceTimer);clearTimeout(autoTimer);++workerJob;solverWorker?.terminate();workerBusy=false;
 const id=workerJob,snapshot=structuredClone(state),key=controlTargetKey(snapshot),[category,control]=controlId.split('.');singleAutoJob={id,key,controlId};syncSingleAutoButtons();syncAuto();
 const finish=(target,reference)=>{if(!singleAutoJob||singleAutoJob.id!==id||controlTargetKey(state)!==key)return;singleAutoCache.set(key,target);if(singleAutoCache.size>12)singleAutoCache.delete(singleAutoCache.keys().next().value);if(reference)installReference(reference);singleAutoJob=null;workerBusy=false;applyControlValue(category,control,target.controls[category][control],true);syncSingleAutoButtons();syncAuto();toast('Auto: applicato solo il valore di questa manovra dall’assetto ottimale complessivo.');};
 const fail=message=>{if(singleAutoJob?.id!==id)return;singleAutoJob=null;workerBusy=false;syncSingleAutoButtons();syncAuto();toast('Ricerca interrotta: '+message);};
 const cached=singleAutoCache.get(key);if(cached){finish(cached);return;}
 if(typeof Worker!=='undefined'){try{solverWorker=new Worker(new URL('./trim-worker.js',import.meta.url),{type:'module'});solverWorker.onmessage=e=>{const m=e.data;if(m.id!==id||singleAutoJob?.id!==id)return;if(m.type==='result')finish(m.target,m.reference);else if(m.type==='error')fail(m.message);};solverWorker.onerror=()=>fail('La ricerca numerica non è stata completata.');solverWorker.postMessage({id,state:snapshot,controlId,reference:getReference(state)});return;}catch{solverWorker=null;}}
 setTimeout(()=>{if(singleAutoJob?.id!==id)return;try{const reference=getReference(snapshot)||computeReference(snapshot),target=optimalControlSettings(snapshot,reference);finish(target,reference);}catch(error){fail(error.message);}},20);
}
function renderControls(){if(!CONTROL_DEFS[controlTab])controlTab='main';$('#profileOverlayToggle').checked=!!state.sailOverlays?.[controlTab];renderControlRows(controlTab,$('#runningControls'));renderControlRows('rig',$('#standingControls'));$$('[data-control]').forEach(b=>b.classList.toggle('active',b.dataset.control===controlTab));updateInspector();}
function updatePlan(){if(!headsailInhaulAllowed(state)&&state.controls.genoa.barber<50){state.controls.genoa.barber=50;if(!controlEnabled(state,'genoa','barber'))state.fixedControls['genoa.barber']=50;}const boat=boatProfile(state),cert=isCertificateBoat(state),head=headsailInfo(state),fore=state.foresail!=='none';names.genoa=head.name;if(!fore&&controlTab!=='main')controlTab='main';
 if(selectedControlId){const [cat,key]=selectedControlId.split('.');if((['genoa','spinnaker','gennaker'].includes(cat)&&cat!==state.foresail&&key!=='car')||(cat==='genoa'&&key==='battens'&&!hasHeadsailBattens(state)))closeDirectControl();}
 $$('.sail-option').forEach(b=>{const available=hasSail(b.dataset.sail,state),active=b.dataset.sail===state.foresail;b.disabled=!available;b.querySelector('.sail-name').textContent=names[b.dataset.sail];b.querySelector('.sail-choice-meta').textContent=available?`${fmt(sailArea(b.dataset.sail,state))} m²`:'Non disponibile';b.title=available?names[b.dataset.sail]+' disponibile':'Non in inventario: crea una vela dalle misure libere';b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});
 $('#noHeadsail').classList.toggle('active',!fore);$('#noHeadsail').setAttribute('aria-pressed',String(!fore));
 $('#headerBoatName').textContent=boat.name;$('#headerBoatName').title=boat.name;$('#selectedBoatName').textContent=boat.name;$('#selectedBoatDetails').textContent=`${boat.sailNo} · ${fmt(boat.length,2)} m · ${boat.id===GENERIC_BOAT.id?'Modello didattico':'ORC '+boat.certificate}`;
 const rigNotice=$('#rigMatchNotice'),fallback=cert&&boat.rig?.match!=='model';rigNotice.classList.toggle('hidden',!fallback);rigNotice.textContent=fallback?`${boat.rig.match==='similar'?'Armo stimato da una barca simile':'Armo da modello compatibile'}: ${boat.rig.model}${boat.rig.sourceVersion?' · '+boat.rig.sourceVersion:''} (${fmt(boat.rig.sourceLoa,2)} m). Fonte ${boat.rig.source}.`:'';
 $('#genoaSizeRow').classList.toggle('hidden',state.foresail!=='genoa'||cert||!!state.sailDesigns.genoa.exploratory);$('#genoaSize').disabled=cert||!!state.sailDesigns.genoa.exploratory;$('#genoaSize').value=state.genoaSize;$('#mainToggle').checked=state.main;$('#mainToggle').closest('.main-sail-card').classList.toggle('is-active',state.main);$('#mainSailStatus').textContent=state.main?'Issata':'Ammainata';$('#noHeadsailHint').textContent=state.main?'Solo randa':'Vele ammainate';
 $('#foreControlTab').classList.toggle('hidden',!fore);$('#foreControlTab').disabled=!fore;$('#foreControlTab').textContent=names[state.foresail];$('#foreControlTab').dataset.control=fore?state.foresail:'main';$('#mainAreaCard').textContent=`${fmt(sailArea('main',state))} m² · ${state.sailDesigns.main.exploratory?'Personalizzata':boat.id===GENERIC_BOAT.id?'Full batten':'Profilo ricostruito'}`;
 const active=[...(state.main?['Randa']:[]),...(fore?[names[state.foresail]+(state.foresail==='genoa'&&!cert&&!state.sailDesigns.genoa.exploratory?' '+state.genoaSize+'%':'')]:[])];$('#planSummary').textContent=active.join(' + ')||'Nessuna vela issata';$('#sailCount').textContent=`${active.length} ${active.length===1?'vela attiva':'vele attive'}`;$('#sailSelectionSize').classList.toggle('hidden',!fore||(state.foresail==='genoa'&&(cert||!!state.sailDesigns.genoa.exploratory)));$('#planTrimShortcut').disabled=!active.length;
 for(const type of ['gennaker','spinnaker']){const input=$('#'+type+'Area'),available=hasSail(type,state);input.closest('label').classList.toggle('hidden',state.foresail!==type);input.disabled=!available;input.readOnly=false;input.title='Superficie libera per esplorazione';input.min='.001';input.removeAttribute('max');if(document.activeElement!==input)input.value=available?selectedArea(type,state).toFixed(2):'';}
 const flying=['spinnaker','gennaker'].includes(state.foresail);$('.flying-areas').classList.toggle('hidden',!flying);$('#flyingMeasurements').classList.toggle('hidden',!flying);if(flying){const d=sailDimensions(state.foresail,state);$('#flyingMeasurements').textContent=`SLU ${fmt(d.SLU,2)} · SLE ${fmt(d.SLE,2)} · SHW ${fmt(d.SHW,2)} · SFL ${fmt(d.SFL,2)} m · ${(d.ratio*100).toFixed(1)}%`;}
 $('#rigDimensionsInfo').innerHTML=rigInformation(boat);$('.design-note').textContent='Misure indipendenti e area libera, anche sulle barche ORC. Il rosso segnala proporzioni insolite senza bloccare la modifica. Le misure non cambiano le vele issate.';
 const n=$('#sailNotice'),custom=['main',state.foresail].filter(t=>t!=='none'&&state.sailDesigns[t]?.exploratory);let text=custom.length?'Vele personalizzate: superficie e forze ricalcolate; polare originale come riferimento. Stima esplorativa.':cert?`Aree iniziali del certificato. ${head.name}: LP/J stimato ${fmt(head.percent,0)}% · sovrapposizione ${fmt(head.overlap,0)}%.`:'';
 if(fore&&state.controls[state.foresail].sheet===0)text+=' Scotta mollata: vela in bandiera, pressione portante scarica e cima lasca.';n.textContent=text.trim();n.classList.toggle('hidden',!text);$('#designArea').textContent=`${fmt(measuredArea(designType,editableDesign(designType,state)),2)} m²`;
}
function showMeasureWarnings(){const m=editableDesign(designType,state),warnings=m.exploratory?designWarnings(designType,m,state):{};for(const [key] of MEASURE_FIELDS[designType]){const row=$('#measure-'+key)?.closest('.measure-row');if(!row)continue;const messages=[...new Set(warnings[key]||[])];row.classList.toggle('unreasonable',!!messages.length);row.querySelector('.measure-warning').textContent=messages.join(' ');for(const input of row.querySelectorAll('input'))input.setAttribute('aria-invalid',String(!!messages.length));}const count=Object.keys(warnings).length;$('#designWarningSummary').textContent=count?'Misure fuori proporzione: valori accettati, ricostruzione e prestazioni indicative.':'';$('#designWarningSummary').classList.toggle('hidden',!count);}

function renderSailMeasures(){const m=editableDesign(designType,state),boat=boatProfile(state);$('#designType').value=designType;$('#sailMeasureFields').innerHTML=MEASURE_FIELDS[designType].map(([key,label])=>{const max=Math.max(m[key]*1.8,boat.length*(key==='P'||key==='HLU'||key==='SLU'||key==='SLE'?2.5:1.4));return `<div class="measure-row"><label for="measure-${key}"><span>${label} <small>m</small></span><input id="measure-${key}" data-measure="${key}" type="number" min="0.001" step="0.001" value="${m[key].toFixed(3)}" inputmode="decimal" aria-describedby="warning-${key}"></label><input data-measure="${key}" type="range" min="0.001" max="${max}" step="0.001" value="${m[key]}" aria-label="${label} in metri" aria-describedby="warning-${key}"><small class="measure-warning" id="warning-${key}"></small></div>`;}).join('');
 $('#sailMeasureFields').querySelectorAll('input').forEach(input=>{if(input.type==='range')styleRange(input);input.addEventListener('input',()=>{if(input.value==='')return;const key=input.dataset.measure,candidate={...editableDesign(designType,state),[key]:Number(input.value),exploratory:true};try{positiveMeasurements(designType,candidate);state.sailDesigns[designType]=candidate;if(['gennaker','spinnaker'].includes(designType))state.sailAreas[designType]=measuredArea(designType,candidate);manual();$('#designError').textContent='';for(const other of $('#sailMeasureFields').querySelectorAll('input')){if(other!==input&&other.dataset.measure===key){if(other.type==='range')other.max=Math.max(Number(other.max),candidate[key]*1.5);other.value=other.type==='number'?candidate[key].toFixed(3):candidate[key];if(other.type==='range')styleRange(other);}}if(input.type==='range')styleRange(input);showMeasureWarnings();updatePlan();if(designType==='genoa')renderControls();updateImmediate();scene?.highlightAffected([`${designType}.sheet`]);}catch(error){$('#designError').textContent=error.message;input.closest('.measure-row').classList.add('unreasonable');input.setAttribute('aria-invalid','true');}});});$('#designError').textContent='';$('#designArea').textContent=`${fmt(measuredArea(designType,m),2)} m²`;showMeasureWarnings();}

$('#designType').addEventListener('change',e=>{designType=e.target.value;renderSailMeasures();});
$('#resetSailDesign').addEventListener('click',()=>{state.sailDesigns[designType]=defaultSailDesigns(boatProfile(state))[designType];if(['gennaker','spinnaker'].includes(designType))state.sailAreas[designType]=boatProfile(state).areas[designType];if(!hasSail(state.foresail,state))state.foresail='none';manual();renderSailMeasures();updatePlan();renderControls();updateImmediate();scene?.highlightAffected([`${designType}.sheet`]);});

function selectBoat(boat){cancelSingleAuto();shapeComparison=null;const old=state;clearTimeout(autoTimer);clearTimeout(initialReferenceTimer);++workerJob;solverWorker?.terminate();workerBusy=false;autoReport=null;closeDirectControl();state=newState(boat);for(const key of ['windSpeed','windAngle','windVisible','windParticleScale','windColor','windDensity','labels','analysis','coefficients','paused'])state[key]=old[key];controlTab=designType='main';speed=equilibrium(state).speed;metric=evaluate(state,speed);history.fill(speed);records.length=0;elapsed=0;updatePlan();renderControls();renderSailMeasures();syncWindInputs();syncAuto();scene?.setView('orbit');updateImmediate();dialog.close();toast(`${boat.name}: polare e inventario caricati.`);autoTimer=setTimeout(()=>requestOptimization(false),120);}
async function boatPicker(){windows.setInfoOwner('boat');const token=showDialog(`<h2>Scegli la barca.</h2><p class="catalog-note">Cerca per nome, modello o numero velico. Seleziona una barca nella lista e premi «Usa questa barca».</p><input id="boatSearch" class="catalog-search" type="search" value="${escapeHTML(pickerQuery)}" placeholder="Cerca fra 1.401 barche ORC…" aria-label="Cerca barca ORC"><p class="catalog-count" id="catalogCount">Caricamento catalogo…</p><select data-i18n-skip id="boatResults" class="catalog-list" size="8" aria-label="Barche disponibili" disabled><option>Caricamento…</option></select><div class="catalog-preview" id="boatPreview"></div><div class="catalog-buttons"><button id="useBoat" class="primary" disabled>Usa questa barca</button><button id="previewCertificate" disabled>Visualizza certificato</button></div><div class="catalog-generic"><button id="genericBoat">Usa lo sloop laboratorio da 10 m</button></div>`);dialog.classList.add('catalog-mode');$('#genericBoat').addEventListener('click',()=>selectBoat(GENERIC_BOAT));try{const boats=await loadBoatCatalog();if(token!==dialogVersion||!dialog.hasAttribute('open'))return;const all=[GENERIC_BOAT,...boats],selected=()=>all.find(b=>b.id===$('#boatResults').value),preview=()=>{const b=selected();pickerChoice=b?.id||null;$('#useBoat').disabled=!b;$('#previewCertificate').disabled=!b||b.id===GENERIC_BOAT.id;$('#boatPreview').innerHTML=b?`<strong data-i18n-skip>${escapeHTML(b.name)}</strong><p>${escapeHTML(b.model)} · ${escapeHTML(b.sailNo)}</p><p>${fmt(b.length,2)} × ${fmt(b.beam,2)} m · Pescaggio ${fmt(b.draft,2)} m · ${fmt(b.displacement,0)} kg</p><p>${[b.areas.main?'Randa':'',b.areas.genoa?'Fiocco / genoa':'',b.areas.spinnaker?'Spinnaker':'',b.areas.gennaker?'Gennaker':''].filter(Boolean).join(' · ')}</p>`:'';},render=()=>{pickerQuery=$('#boatSearch').value||'';const matches=findBoats(boats,pickerQuery).sort((a,b)=>a.name.localeCompare(b.name,'it')),includeGeneric=!pickerQuery.trim()||findBoats([GENERIC_BOAT],pickerQuery).length,options=[...(includeGeneric?[GENERIC_BOAT]:[]),...matches],preferred=options.find(b=>b.id===pickerChoice)||options.find(b=>b.id===boatProfile(state).id)||options[0];$('#catalogCount').textContent=`${matches.length.toLocaleString(getLocale())} di ${boats.length.toLocaleString(getLocale())} barche ORC`;$('#boatResults').disabled=!options.length;$('#boatResults').innerHTML=options.length?options.map(b=>`<option value="${escapeHTML(b.id)}"${b.id===preferred?.id?' selected':''}>${escapeHTML(b.name)} — ${escapeHTML(b.model)} · ${escapeHTML(b.sailNo)} · ${fmt(b.length,2)} m</option>`).join(''):'<option value="">Nessuna barca trovata</option>';preview();};$('#boatSearch').addEventListener('input',render);$('#boatResults').addEventListener('change',preview);const apply=()=>{const b=selected();if(b)selectBoat(b);};$('#useBoat').addEventListener('click',apply);$('#boatResults').addEventListener('dblclick',apply);$('#boatResults').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();apply();}});$('#previewCertificate').addEventListener('click',()=>{const b=selected();if(b&&b.id!==GENERIC_BOAT.id)certificateView(b,true);});render();$('#boatSearch').focus();}catch(error){if(token===dialogVersion&&$('#catalogCount')){$('#catalogCount').textContent=error.message;$('#boatPreview').innerHTML='<button class="text-button" id="retryCatalog">Riprova caricamento</button>';$('#retryCatalog').addEventListener('click',boatPicker);}}}
function rigInformation(boat){const probe={...state,boat,sailDesigns:defaultSailDesigns(boat)},r=rigDimensions(probe),k=boat.length/10,source=boat.rig,h=headsailInfo(probe),fraction=r.foreFraction<.985,estimated=new Set(source?.estimatedFields||['ISP','SPL','TPS']),values=[['P',source?.P||r.P*k],['E',source?.E||r.E*k],['I',r.I*k],['J',r.J*k],['Isp',r.Isp*k],['SPL',r.SPL*k],['TPS',r.TPS*k]],label=source?.riggingType||`${fraction?'Armo frazionato stimato':'Armo in testa stimato'}`;return `<b>${escapeHTML(label)} · strallo al ${fmt(r.foreFraction*100,0)}%</b><div class="rig-dimensions-grid">${values.map(([key,value])=>`<span title="${escapeHTML(source?.estimates?.[key==='Isp'?'ISP':key]||'Dimensione del modello di riferimento')}">${key}${estimated.has(key==='Isp'?'ISP':key)?' *':''}<strong>${fmt(value,2)} m</strong></span>`).join('')}</div><small>${source?`Fonte ${escapeHTML(source.source)} · ${source.match==='model'?'modello corrispondente':source.match==='compatible'?'modello compatibile':'modello simile, scalato sulla lunghezza'}: ${escapeHTML(source.model)}${source.sourceVersion?' · '+escapeHTML(source.sourceVersion):''}${source.match==='similar'?` (${fmt(source.sourceLoa,2)} m, scala ${fmt(source.scale,3)})`:''}.`:'Armo parametrico del laboratorio.'} * Isp, SPL e TPS sono stime dichiarate: altezza e tipo d’armo disponibili, tangone assunto lungo J e bompresso stimato. Lande ${standingRigLayout(probe).inboard?'interne per vela sovrapposta':'in falchetta per vela non sovrapposta'} · ${fmt(standingRigLayout(probe).chainplateX*k,2)} m dal centro. Superfici e polare esclusivamente ORC. ${h.name} · LP/J ricostruito ${fmt(h.percent,0)}% · sovrapposizione ${fmt(h.overlap,0)}%.</small>`;}

async function certificateView(boat=boatProfile(state),fromPicker=false){windows.setInfoOwner('certificate');if(boat.id===GENERIC_BOAT.id){boatPicker();return;}const token=showDialog(`<h2>Certificato ORC</h2><p class="certificate-loader">Caricamento dati di ${escapeHTML(boat.name)}…</p>`);dialog.classList.add('certificate-mode');try{const meta=await loadCertificate(boat.id);if(token!==dialogVersion||!dialog.hasAttribute('open'))return;const record=meta.record;$('#dialogContent').innerHTML=`${fromPicker?'<button id="certificateBack" class="certificate-back">← Torna alla scelta della barca</button>':''}<h2 data-i18n-skip>${escapeHTML(record.YachtName)}</h2><p class="certificate-subtitle">${escapeHTML(record.Class)} · ${escapeHTML(record.SailNo)} · Certificato ${escapeHTML(record.CertNo)} · Emesso ${escapeHTML(String(record.IssueDate).slice(0,10))}</p><p class="certificate-unit-note">Tutti i dati originali presenti in ${escapeHTML(meta.source)}. Le modifiche alle vele nel laboratorio non cambiano questo certificato.</p><div class="rig-dimensions-card">${rigInformation(boat)}</div><div class="certificate-toolbar"><button id="certificateChoose" class="primary"${boat.id===boatProfile(state).id?' disabled':''}>${boat.id===boatProfile(state).id?'Barca attiva':'Usa questa barca'}</button><button id="certificateChange">Scegli un’altra barca</button><button id="certificateDownload">Scarica JSON completo</button></div><div class="certificate-tabs" role="tablist" aria-label="Sezioni del certificato">${[['overview','Panoramica'],['sails','Vele'],['polar','Polare'],['ratings','Rating'],['all','Tutti i dati']].map(([key,label])=>`<button data-cert-tab="${key}" role="tab" aria-selected="${key==='overview'}" aria-controls="certificateContent" class="${key==='overview'?'active':''}">${label}</button>`).join('')}</div><input id="certificateFilter" class="certificate-filter" type="search" placeholder="Filtra i campi della sezione…" aria-label="Filtra i dati del certificato"><p id="certificateCount" class="certificate-count"></p><div id="certificateContent" role="tabpanel"></div>`;let section='overview';const render=()=>{const query=$('#certificateFilter').value||'';$('#certificateContent').innerHTML=certificateTable(record,meta,section,query);$('#certificateCount').textContent=`${certificateFields(record,meta,section,query).length} campi nella sezione · ${flattenCertificate(record).length} campi complessivi nel record`;};$$('[data-cert-tab]').forEach((button,index,buttons)=>{button.addEventListener('click',()=>{section=button.dataset.certTab;for(const b of buttons){b.classList.toggle('active',b===button);b.setAttribute('aria-selected',b===button);}render();});button.addEventListener('keydown',e=>{const delta={ArrowLeft:-1,ArrowRight:1}[e.key];if(delta){e.preventDefault();const next=buttons[(index+delta+buttons.length)%buttons.length];next.click();next.focus();}});});$('#certificateFilter').addEventListener('input',render);$('#certificateChoose').addEventListener('click',()=>selectBoat(boat));$('#certificateChange').addEventListener('click',boatPicker);$('#certificateBack')?.addEventListener('click',boatPicker);$('#certificateDownload').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`ORC-${record.BIN}-${record.CertNo}`.replace(/[^a-zA-Z0-9_-]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});render();}catch(error){if(token===dialogVersion){$('#dialogContent').innerHTML=`<h2>Certificato ORC</h2><p class="certificate-error">${escapeHTML(error.message)}</p><button id="retryCertificate" class="dialog-action">Riprova</button>`;$('#retryCertificate').addEventListener('click',()=>certificateView(boat,fromPicker));}}}
$$('[data-pick-boat]').forEach(button=>button.addEventListener('click',()=>windows.toggleInfo('boat',boatPicker)));
function changeControlEnabled(id,enabled){const [category,key]=id.split('.'),focused=document.activeElement?.dataset?.controlEnabled===id;cancelSingleAuto();clearTimeout(autoTimer);clearTimeout(initialReferenceTimer);++workerJob;solverWorker?.terminate();workerBusy=false;setControlEnabled(state,category,key,enabled);autoReport=null;autoCarTarget=null;renderControls();if(focused)$(`[data-control-enabled="${id}"]`)?.focus({preventScroll:true});updateImmediate();syncAuto();if(state.auto)autoTimer=setTimeout(()=>requestOptimization(true),80);}
function manual(){cancelSingleAuto();autoReport=null;autoCarTarget=null;if(state.auto){state.auto=false;syncAuto();toast('Regolazione manuale attiva.');}}
function syncAuto(){
 if(workerBusy){solverProgress({progress:0});return;}
 $('#autoButton').setAttribute('aria-busy','false');$('#autoButton').setAttribute('aria-pressed',state.auto);$('#autoButton>span').textContent=state.auto?'Assetto automatico attivo':'Assetto automatico';$('#autoButton small').textContent=state.auto?'ON':'AUTO';
 $('#autoDescription').textContent=!state.auto?'Ottimizza le manovre abilitate; conserva vele e valori fissati. A parità di target privilegia i segnavento a segno.':autoReport?.constraintsFeasible===false?'Vincoli incompatibili: libera una manovra o modifica il taglio. I valori fissati sono conservati.':autoLiveConstraintBlocked?'Carrello fissato: verifica il rinvio durante l’assestamento della vela.':!autoReport?'Ricerca di velocità e flusso per le vele scelte.':autoReport.targetReached?(autoReport.flowReached?'Target di polare e segnavento a segno nel modello.':'Target di polare raggiunto; resta separazione su alcune sezioni.'):autoReport.flowReached?'Miglior assetto trovato con segnavento a segno; target non raggiunto.':'Miglior compromesso trovato fra target e flusso per queste vele e vincoli.';
}

function solverProgress(message){workerBusy=true;$('#autoButton').setAttribute('aria-busy','true');$('#autoButton>span').textContent=state.auto?'Ricerca assetto…':'Assetto automatico';$('#autoButton small').textContent=`${Math.round((message.progress||0)*95)}%`;$('#autoDescription').textContent=state.auto?'Ottimizzazione delle manovre della vela scelta…':'Calcolo del riferimento della polare…';}
function finishOptimization(message,id,applyAuto){if(id!==workerJob||message.reference.key!==referenceKey(state))return;installReference(message.reference);workerBusy=false;$('#autoButton').setAttribute('aria-busy','false');if(applyAuto&&state.auto&&message.solution){const solution=message.solution;shapeComparison={id:'auto',time:performance.now(),before:Object.fromEntries(['main',state.foresail].filter(t=>t!=='none').map(t=>[t,shapeSummary(t,state)]))};const previousControls=state.controls;state.controls=structuredClone(solution.state.controls);restoreFixedControls(state);autoCarTarget=state.controls.genoa.car;autoReport=solution;controlTab=controlTab==='main'?'main':state.foresail;updatePlan();renderControls();scene?.highlightAffected(Object.entries(CONTROL_DEFS).flatMap(([c,defs])=>defs.filter(d=>controlEnabled(state,c,d[0])&&Math.abs(previousControls[c][d[0]]-state.controls[c][d[0]])>.001).map(d=>`${c}.${d[0]}`)));toast(solution.constraintsFeasible===false?'Vincoli incompatibili: i valori fissati restano invariati.':solution.targetReached?(solution.flowReached?'Target di polare e segnavento a segno nel modello.':'Target di polare raggiunto; resta separazione su alcune sezioni.'):`Miglior equilibrio trovato: ${fmt(solution.achievable)}% della polare con queste vele.`);}syncAuto();updateImmediate();}
function requestOptimization(applyAuto=state.auto){cancelSingleAuto();const id=++workerJob,snapshot=structuredClone(state),existing=getReference(state);if(existing&&!applyAuto){workerBusy=false;syncAuto();updateImmediate();return;}workerBusy=true;solverProgress({progress:0});if(solverWorker)solverWorker.terminate();
 if(typeof Worker!=='undefined'){try{solverWorker=new Worker(new URL('./trim-worker.js',import.meta.url),{type:'module'});solverWorker.onmessage=e=>{const m=e.data;if(m.id!==workerJob)return;if(m.type==='progress')solverProgress(m);else if(m.type==='result')finishOptimization(m,id,applyAuto);else{workerBusy=false;syncAuto();toast('Ricerca interrotta: '+m.message);}};solverWorker.onerror=()=>{if(id!==workerJob)return;workerBusy=false;syncAuto();toast('La ricerca numerica non è stata completata.');};solverWorker.postMessage({id,state:snapshot,applyAuto,reference:existing});return;}catch(error){solverWorker=null;}}
 // Same solver as a fallback in browsers without module workers.
 setTimeout(()=>{if(id!==workerJob)return;try{const reference=existing||computeReference(snapshot),solution=applyAuto?optimizeForReference(snapshot,reference):null;finishOptimization({reference,solution},id,applyAuto);}catch(error){workerBusy=false;syncAuto();toast(error.message);}},20);
}
function runAuto(){autoCarTarget=null;keepAutoCarBehindClew();clearTimeout(initialReferenceTimer);clearTimeout(autoTimer);requestOptimization(state.auto);}
function onWindChange(){cancelSingleAuto();autoReport=null;shapeComparison=null;clearTimeout(initialReferenceTimer);clearTimeout(autoTimer);++workerJob;workerBusy=false;updatePlan();updateImmediate();autoTimer=setTimeout(()=>requestOptimization(state.auto),220);}
function syncWindInputs(){syncWindAppearance();$('#windSpeed').value=state.windSpeed;$('#windAngle').value=state.windAngle;styleRange($('#windSpeed'));styleRange($('#windAngle'));$('#windSpeedOutput').textContent=`${fmt(state.windSpeed,state.windSpeed%1?1:0)} kn`;$('#windAngleOutput').textContent=`${state.windAngle>0?'+':''}${fmt(state.windAngle,0)}°`;$('#windValue').textContent=fmt(state.windSpeed);$('#windCompact').textContent=`${fmt(state.windSpeed,state.windSpeed%1?1:0)} kn · ${Math.abs(state.windAngle)}°`;$('#windAngleValue').textContent=`${Math.abs(state.windAngle)}°`;$('#courseName').textContent=courseName(state.windAngle);$('#instrumentTws').textContent=`${fmt(state.windSpeed)} kn`;$('#instrumentTwa').textContent=`${Math.abs(state.windAngle)}° ${state.windAngle===0?'da prua':Math.abs(state.windAngle)===180?'da poppa':state.windAngle>0?'da dritta':'da sinistra'}`;$('#dialArrow').style.transform=`rotate(${state.windAngle}deg)`;const ends=$('[data-ends="main.traveler"]'),travelerSpec=controlSpec('main','traveler');if(ends){ends.children[0].textContent=travelerSpec.low;ends.children[1].textContent=travelerSpec.high;}$('#windDial').setAttribute('aria-valuenow',state.windAngle);$('#windDial').setAttribute('aria-valuetext',`${Math.abs(state.windAngle)} gradi ${state.windAngle>=0?'da dritta':'da sinistra'}, ${courseName(state.windAngle)}`);}
$('#windSpeed').addEventListener('input',e=>{state.windSpeed=Number(e.target.value);syncWindInputs();onWindChange();});
$('#windAngle').addEventListener('input',e=>{state.windAngle=Number(e.target.value);syncWindInputs();onWindChange();});
const dial=$('#windDial');function dialMove(e){const r=dial.getBoundingClientRect();const a=Math.round(Math.atan2(e.clientX-r.left-r.width/2,-(e.clientY-r.top-r.height/2))*180/Math.PI);state.windAngle=a;syncWindInputs();onWindChange();}
dial.addEventListener('pointerdown',e=>{dial.setPointerCapture(e.pointerId);dialMove(e);});dial.addEventListener('pointermove',e=>{if(dial.hasPointerCapture(e.pointerId))dialMove(e);});dial.addEventListener('keydown',e=>{const direction={ArrowLeft:-1,ArrowDown:-1,ArrowRight:1,ArrowUp:1}[e.key];if(direction){e.preventDefault();state.windAngle=clamp(state.windAngle+direction*(e.shiftKey?10:1),-180,180);syncWindInputs();onWindChange();}});
function chooseForesail(type){cancelSingleAuto();if(type!=='none'&&!hasSail(type,state))return;autoReport=null;state.foresail=type;controlTab=type==='none'?'main':type;updatePlan();renderControls();updateImmediate();if(state.auto)runAuto();}
$$('.sail-option').forEach(b=>b.addEventListener('click',()=>chooseForesail(state.foresail===b.dataset.sail?'none':b.dataset.sail)));
$('#noHeadsail').addEventListener('click',()=>chooseForesail('none'));
function primarySail(){return controlTab==='main'&&state.main?'main':state.foresail!=='none'?state.foresail:'main';}
$('#planTrimShortcut').addEventListener('click',()=>{controlTab=primarySail();renderControls();panelTab('sails');$('#sailsTab').focus({preventScroll:true});});
$('#planMeasuresShortcut').addEventListener('click',()=>{designType=primarySail();renderSailMeasures();panelTab('measures');$('#measuresTab').focus({preventScroll:true});});

$('#genoaSize').addEventListener('change',e=>{cancelSingleAuto();if(isCertificateBoat(state))return;autoReport=null;state.genoaSize=Number(e.target.value);updatePlan();renderControls();updateImmediate();if(state.auto)runAuto();});
for(const type of ['gennaker','spinnaker'])$('#'+type+'Area').addEventListener('change',e=>{const value=Number(e.target.value);if(!Number.isFinite(value)||value<=0||!hasSail(type,state))return;try{resizeFlyingDesign(type,state,value);manual();updatePlan();if(designType===type)renderSailMeasures();updateImmediate();scene?.highlightAffected([`${type}.sheet`]);}catch(error){toast(error.message);e.target.value=selectedArea(type,state).toFixed(2);}});

$('#mainToggle').addEventListener('change',e=>{cancelSingleAuto();autoReport=null;state.main=e.target.checked;updatePlan();updateImmediate();if(state.auto)runAuto();});
$('#controlTabs').addEventListener('click',e=>{const b=e.target.closest('[data-control]');if(!b)return;controlTab=b.dataset.control;renderControls();});
function panelTab(tab){if(typeof tab==='boolean')tab=tab?'rig':'sails';for(const name of ['plan','sails','rig','measures']){const selected=name===tab,section=$(name==='plan'?'#planSectionPanel':'#'+name+'Section'),button=$('#'+name+'Tab');section.classList.toggle('hidden',!selected);section.inert=!selected;button.classList.toggle('active',selected);button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;}}
const trimTabs=$$('.panel-tabs [role=tab]');trimTabs.forEach((button,index)=>{button.addEventListener('click',()=>panelTab(button.dataset.trimTab));button.addEventListener('keydown',e=>{const step={ArrowLeft:-1,ArrowRight:1}[e.key];let next;if(step)next=(index+step+trimTabs.length)%trimTabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=trimTabs.length-1;if(next!==undefined){e.preventDefault();trimTabs[next].click();trimTabs[next].focus();}});});

$('#autoButton').addEventListener('click',()=>{cancelSingleAuto();state.auto=!state.auto;if(state.auto){runAuto();}else{syncAuto();toast('Assetto automatico disattivato.');}});
$('#analysisButton').addEventListener('click',()=>{state.analysis=!state.analysis;$('#analysisButton').setAttribute('aria-pressed',state.analysis);$('#pressureLegend').classList.toggle('hidden',!state.analysis);if(state.analysis)toast('Pressione calcolata sui pannelli della vela; lift e drag derivano dalla stessa integrazione.');});
$('#coeffToggle').addEventListener('change',e=>{state.coefficients=e.target.checked;if(state.coefficients)setFold('telemetry','telemetryFold',false);$('#coefficientPanel').classList.toggle('hidden',!state.coefficients);updateUI();});
$('#windVisibility').addEventListener('click',()=>{state.windVisible=!state.windVisible;$('#windVisibility').classList.toggle('selected',state.windVisible);$('#windVisibility').setAttribute('aria-pressed',state.windVisible);syncWindAppearance();});
$('#windDensity').addEventListener('input',e=>{state.windDensity=windLayout(Number(e.target.value)/100).density;syncWindAppearance();saveWindAppearance();});
$('#windParticleSize').addEventListener('input',e=>{const scale=Number(e.target.value)/100;if(!Number.isFinite(scale))return;state.windParticleScale=clamp(scale,.5,2.5);syncWindAppearance();saveWindAppearance();});
$('#windColor').addEventListener('input',e=>{if(!/^#[0-9a-f]{6}$/i.test(e.target.value))return;state.windColor=e.target.value.toLowerCase();syncWindAppearance();saveWindAppearance();});

function setView(view){scene?.setView(view);$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('#resetView').addEventListener('click',()=>setView('orbit'));$('#zoomIn').addEventListener('click',()=>scene?.zoomBy(.80));$('#zoomOut').addEventListener('click',()=>scene?.zoomBy(1.25));$('#panView').addEventListener('click',()=>{const pan=$('#panView').getAttribute('aria-pressed')!=='true';$('#panView').setAttribute('aria-pressed',pan);$('#panView').classList.toggle('selected',pan);scene?.setNavigationMode(pan);});
$('#audioButton').addEventListener('click',async()=>{try{const enabled=await audio.toggle();$('#audioButton').setAttribute('aria-pressed',enabled);$('#audioButton use').setAttribute('href',enabled?'#i-sound':'#i-muted');$('#audioButton>span').textContent=enabled?'Suoni attivi':'Attiva suoni';if(state.paused)audio.pause(true);}catch(e){toast(e.message);}});
function syncPause(){$('#pauseButton').setAttribute('aria-pressed',state.paused);$('#pauseButton').setAttribute('aria-label',state.paused?'Riprendi simulazione':'Pausa simulazione');$('#pauseButton').title=state.paused?'Riprendi simulazione':'Pausa simulazione';$('#pauseButton use').setAttribute('href',state.paused?'#i-play':'#i-pause');$('#pauseButton>span').textContent=state.paused?'Riprendi':'Pausa';audio.pause(state.paused);}
$('#pauseButton').addEventListener('click',()=>{state.paused=!state.paused;syncPause();});
$('#resetButton').addEventListener('click',()=>{cancelSingleAuto();shapeComparison=null;closeDirectControl();clearTimeout(autoTimer);++workerJob;solverWorker?.terminate();workerBusy=false;autoReport=null;state=newState(state.boat);restoreWindAppearance();designType='main';renderSailMeasures();speed=equilibrium(state).speed;metric=evaluate(state,speed);history.fill(speed);records.length=0;elapsed=0;controlTab='main';updatePlan();renderControls();syncWindInputs();syncAuto();syncPause();panelTab('plan');$('#analysisButton').setAttribute('aria-pressed',false);$('#pressureLegend').classList.add('hidden');$('#coeffToggle').checked=false;$('#coefficientPanel').classList.add('hidden');for(const id of ['windVisibility']){$('#'+id).classList.add('selected');$('#'+id).setAttribute('aria-pressed',true);}setView('orbit');updateUI();drawChart();toast('Laboratorio ripristinato: 12 kn, bolina a 45°.');requestOptimization(false);});
function keepAutoCarBehindClew(){
 if(!state.auto||state.foresail!=='genoa'){autoLiveConstraintBlocked=false;return;}
 const previous=state.controls.genoa.car,blocked=!constrainAutoJibCar(state,autoCarTarget??previous);
 if(blocked)autoCarTarget=null;
 if(blocked!==autoLiveConstraintBlocked){autoLiveConstraintBlocked=blocked;syncAuto();}
 if(Math.abs(previous-state.controls.genoa.car)>.00001)syncControlInputs('genoa','car');
}

function updateImmediate(){state.boatSpeed=speed;advanceJibDynamics(state,0);keepAutoCarBehindClew();metric=evaluate(state,speed);updateUI();updateInspector();}
function updateUI(){updateProfileOverlays();syncDirectControl();const m=metric;$('#boatSpeed').textContent=fmt(speed);$('#apparentWind').textContent=fmt(m.aws);$('#awaValue').textContent=`${fmt(Math.abs(m.awa),0)}°`;$('#efficiency').textContent=fmt(m.polarEfficiency,0);$('#efficiencyBar').style.width=`${clamp(m.polarEfficiency,0,100)}%`;$('#heelValue').textContent=fmt(m.heel);$('#heelCaption').textContent=m.heel>25?'Barca sovrainvelata':m.heel<5?'Carico leggero':'Carico equilibrato';$('#historySpeed').textContent=`${fmt(speed)} kn`;
 $('#polarTarget').textContent=fmt(m.polarTarget);$('#solverData').textContent=`${m.panelCount} pannelli · residuo ${m.residual<1e-8?'< 10⁻⁸':m.residual.toExponential(1)} · flusso potenziale`;
 const noGo=Math.abs(state.windAngle)<30,calm=state.windSpeed<.5;
 $('#speedStatus').textContent=calm?'In attesa di vento':noGo?'Prua al vento':m.efficiency>90?'Assetto in equilibrio':m.efficiency>65?'Regolazione migliorabile':'Flusso da ritrovare';
 let title='Flusso aderente',text='I segnavento scorrono paralleli: la vela lavora bene.';
 if(calm){title='Il vento si è fermato';text='Aumenta l’intensità per mettere in movimento vele e segnavento.';}
 else if(noGo){title='Sei nella zona morta';text='Poggia oltre 35–40°: le vele torneranno a generare spinta.';}
 else if(m.heel>27){title='Riduci il carico';text=isCertificateBoat(state)?'Appiattisci la randa e apri il carrello. Valuta la vela disponibile più adatta.':'Appiattisci la randa, apri il carrello e scegli il fiocco 105%.';}
 else if(!m.sails.length){title='Nessuna vela issata';text='Issa la randa o scegli una vela di prua per riprendere la navigazione.';}
 else if(!m.telltales.allAttached){const sail=m.telltales.sails.reduce((a,b)=>a.loss>b.loss?a:b);title=Math.abs(m.awa)>110?'Flusso alle portanti':`${names[sail.type]} da regolare`;text=Math.abs(m.awa)>110?'In poppa il flusso può separarsi anche nell’assetto migliore. Osserva ogni vela e la superficie esposta.':'Controlla scotta, carrello e svergolamento; confronta i nastri sui due lati della vela.';}
 else if((state.foresail==='spinnaker'&&Math.abs(state.windAngle)<120)||(state.foresail==='gennaker'&&Math.abs(state.windAngle)<75)){title='Scegli una vela più adatta';text=`Questa vela rende meglio a un’andatura più larga. Seleziona ${headsailInfo(state).name.toLowerCase()} per risalire il vento; AUTO ottimizza la vela scelta.`;}
 else if(m.efficiency<90){title='Puoi trovare più equilibrio';text='Regola le scotte e osserva i segnavento lungo l’altezza delle vele.';}
 $('#feedbackTitle').textContent=title;$('#feedbackText').textContent=text;
 if(state.analysis)$('#pressureMax').textContent=`${fmt(m.maxPressure,0)} Pa`;
 $('#autoQuality').classList.toggle('hidden',!m.referenceReady);if(m.referenceReady){$('#referenceForce').textContent=`${fmt(m.usefulDrive,0)} / ${fmt(m.referenceScore,0)} N`;$('#referencePressure').textContent=`${fmt(m.cp95,2)} / ${fmt(m.referenceCp95,2)}`;$('#referenceFlow').textContent=`${fmt(m.attachment*100,0)}%`;$('#referenceTelltales').textContent=`${m.telltales.attached} / ${m.telltales.total}`;$('#referenceTelltalesBySail').textContent=m.telltales.sails.map(f=>`${names[f.type]}: ${f.attached}/${f.total}`).join(' · ');$('#referenceStatus').textContent=state.auto&&autoReport?.constraintsFeasible===false?'Manovre fissate incompatibili con il rinvio automatico':state.auto&&autoReport?.targetReached?'Assetto al target · velocità in assestamento':'Confronto con l’assetto di riferimento';}
 if(state.coefficients){$('#totalArea').textContent=`${fmt(m.area)} m²`;$('#liftCoefficient').textContent=fmt(m.cl,2);$('#dragCoefficient').textContent=fmt(m.cd,2);$('#liftForce').textContent=`${fmt(m.lift,0)} N`;$('#dragForce').textContent=`${fmt(m.drag,0)} N`;$('#sailCoefficientRows').innerHTML=m.sails.map(v=>`<span>${names[v.type]} <b>C<sub>L</sub> ${fmt(v.cl,2)}</b> · C<sub>D</sub> ${fmt(v.cd,2)} · ${fmt(v.area)} m²</span>`).join('');}
 updateInspector();
}
function drawChart(){const max=Math.max(8,...history)*1.1;const points=history.map((v,i)=>`${i/60*250},${51-v/max*43}`);$('#chartLine').setAttribute('d','M'+points.join(' L'));$('#chartArea').setAttribute('d','M0,58 L'+points.join(' L')+' L250,58 Z');}
const dialog=$('#infoDialog');function showDialog(html){++dialogVersion;dialog.classList.remove('catalog-mode','certificate-mode');$('#dialogContent').innerHTML=html;if(!dialog.hasAttribute('open')){if(dialog.show)dialog.show();else dialog.setAttribute('open','');}windows.anchor(dialog);return dialogVersion;}
dialog.addEventListener('close',()=>{++dialogVersion;});
$('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function guide(){windows.setInfoOwner('guide');showDialog(guideHTML());$('#startExploring').addEventListener('click',()=>dialog.close());}
function credits(){windows.setInfoOwner('credits');showDialog(aboutHTML());$('#aboutModelLink').addEventListener('click',modelInfo);}
function modelInfo(){windows.setInfoOwner('about');const boat=boatProfile(state),catalog=!!boat.polar;showDialog(`<h2>La barca e il modello.</h2><h3 data-i18n-skip>${escapeHTML(boat.name)} · ${escapeHTML(boat.model)}</h3><p>${catalog?`Dati caricati dall’allegato <b>ITA_ORC.json</b>, certificato ${escapeHTML(boat.certificate)}, emesso il ${escapeHTML(boat.issued)}. Il file dichiara dimensioni, aree e tipologie di vela; non contiene corde, piano di forme, rigidezze o il dettaglio di ogni vela fisica.`:'Sloop generico da 10 m, basato sui precedenti certificati allegati e scalato geometricamente.'}</p><table class="model-table"><tr><td>Lunghezza / baglio</td><td>${fmt(boat.length,2)} / ${fmt(boat.beam,2)} m</td></tr><tr><td>Pescaggio / dislocamento</td><td>${fmt(boat.draft,2)} m / ${fmt(boat.displacement,0)} kg</td></tr>${['main','genoa','spinnaker','gennaker'].map(t=>`<tr><td>${names[t]} · area del file</td><td>${boat.areas[t]>0?fmt(boat.areas[t],2)+' m²':'Non dichiarata'}</td></tr>`).join('')}</table><div class="rig-dimensions-card">${rigInformation(boat)}</div><h3>Polare del certificato</h3><p>${catalog?'Le righe R52…R150 sono tempi in secondi per miglio: velocità = 3600 / tempo. Beat e Run sono dati di VMG; gli estremi all’angolo ottimale si ricavano dividendo anche per |cos(angolo)|. Interpoliamo le velocità fra i venti e gli angoli del file, senza riscalare la polare a 10 m.':'La polare iniziale deriva da NEXT GEN, allegato Asimmetrico.pdf, con velocità scalate a 10 m.'} Fuori dalle condizioni tabulate usiamo un raccordo didattico; oltre l’ultimo angolo di poppa disponibile la velocità diretta è una stima, non un valore fornito nel file. I tempi di percorsi aggregati DW/CR/WL non sono trattati come velocità puntuali.</p><h3>Corde e forme modificabili</h3><p>In «Misure & corde» ogni misura è indipendente: randa P/E/MQW/MHW/MTW/MUW/MHB, fiocco HLU/HLP/HQW/HHW/HTW/HUW/HHB e portanti SLU/SLE/SFL/SHW. Le modifiche non compensano altre corde né mantengono un’area fissa. Il rosso segnala rapporti fuori guida, limiti dell’armo e lunghezze incompatibili; i valori positivi vengono comunque accettati. Quando una ricostruzione regolare non esiste, grafica e pressioni condividono una superficie approssimata per esplorazione. Non rappresenta un taglio realizzabile o una previsione certificata.</p><p>Le aree usano le formule ORC 2026, articoli 109, 111, 113 e 114. Per i portanti A = [(SLU + SLE) / 2] (SFL + 4 SHW) / 6; sul simmetrico SLU = SLE. SHW deve essere almeno 0,75 SFL. Le famiglie di taglio regolari rispettano le lunghezze e la corda media mediante soluzione numerica. Forma gonfia, grasso e rigidezze restano una ricostruzione: il file non determina una superficie 3D univoca.</p><p>Le aree iniziali e la polare vengono dal certificato ORC. sailing_database.json e gold-boat.json forniscono P/E/I/J e i riferimenti d’armo. Le vele modificate usano invece l’area delle misure inserite; il certificato e la polare originali non cambiano. Ripristina questa vela recupera la ricostruzione iniziale. Puoi anche creare una vela esplorativa non dichiarata nel certificato modificandone le misure nell’editor e poi issandola dal piano velico.</p><h3>Portanti 3D e altezza del tangone</h3><p>Le ralinghe in volo sono archi quadratici risolti alla lunghezza SLU/SLE. Le sezioni sono due archi circolari tangenti al massimo grasso: R = (a² + h²) / (2h), angolo θ = 2 atan(h/a), lunghezza Rθ. La soluzione conserva SFL sulla base e SHW fra i punti a metà delle ralinghe anche sulla superficie 3D. La corsa utile si arresta prima del contatto con lo strallo; la testa resta sulla drizza esterna. Il comando unico Caricalto / caricabasso alza la varea mantenendo SPL. La quota delle bugne influenza il recupero di pressione: un dislivello eccessivo riduce gradualmente le stesse celle Δp usate per mappa, lift e drag. AUTO ottimizza anche la quota del tangone. Il fattore di stabilità è empirico; il riferimento di assetto è descritto nella <a href="https://support.seldenmast.com/files/595-560-E.pdf" target="_blank" rel="noopener">guida Seldén</a>.</p><h3>Scotte, barber e armo</h3><p>Le scotte tirano dal centro della puleggia del rispettivo carrello. Sul fiocco/genoa la scotta tira la bugna verso il rinvio reale, opponendosi al vento apparente. Lascando la vela si apre e può sollevare la bugna; cazzando si chiude e la bugna tende al carrello o al barber. Inferitura, HLP, base e balumina inferite limitano il movimento: l’allineamento verticale sopra il carrello non è possibile con qualsiasi posizione o taglio. Sul fiocco il percorso dal winch è carrello → rinvio barber → bugna. Oltre il 105% LP/J il barber interno è escluso: restano centro e apertura esterna. Con vele più piccole il singolo barber è bidirezionale: a 0 il rinvio è sul carrello, valori negativi lo avvicinano all’albero, positivi lo portano all’esterno. Sposta il punto di tiro effettivo: carrello, barber e scotta agiscono insieme sull’apertura e sulla chiusura della balumina. A scotta completamente mollata il fiocco si allinea al flusso e perde la pressione portante; resta una resistenza residua d’attrito. Cime e segnavento mostrano la condizione. Le quattro scotte usano tutta la corsa utile proporzionalmente, da vela libera al massimo avvicinamento al rinvio consentito dall’armo. Il braccio del simmetrico conserva la corsa ampliata.</p><p>Carico, freccia dello strallo e prebend usano un modello meccanico quasi statico con tensioni e rigidezze assunte. La randa viene limitata prima delle sartie. La risposta di strallo e sartie usa limiti morbidi, senza arresti improvvisi della deformazione; sartie e strallo contribuiscono anche alla flessione longitudinale dell’albero. Scafo e hardware sono parametrici, adattati a lunghezza e baglio: non sono la carena rilevata di ogni modello del catalogo.</p><h3>Equilibrio della vela di prua</h3><p>La bugna ruota attorno all’inferitura sotto tiro della scotta, carico del vento apparente e peso del tessuto, con dimensioni inferite conservate. La percentuale dello slider rappresenta la corsa geometrica utile: 0% libero nel vento, 100% nel punto ammissibile più vicino al rinvio, con progressione proporzionale. La tensione è stimata dal carico e dalla leva; il vincolo geometrico comprende la reazione di battuta e il limite delle sartie/crocette. Nel movimento reale della scena un’integrazione angolare con inerzia equivalente del tessuto e dell’aria, smorzata vicino al regime critico, porta la bugna verso l’equilibrio. Pressioni e velocità usano la posizione corrente; AUTO cerca invece il regime stazionario. Il tiro segue la direzione bugna–rinvio; il suo componente verticale contribuisce a chiudere la balumina e quello lungo la base ad appiattire il piede. La stima assume un massimo di tiro di 18 kN sul riferimento da 10 m e massa di tessuto equivalente 0,24 kg/m²: non sono valori misurati del certificato. Base randa e stecche contribuiscono alla forma e alle pressioni: il tiro della base muove la bugna senza accorciare il boma, mentre il sostegno delle stecche ha un carico ottimale progressivo con il vento. La forma è valutata con il vento apparente alla velocità effettiva della barca; la stessa superficie viene usata nelle pressioni. È un equilibrio meccanico ridotto, non una soluzione completa dell’elasticità della membrana o delle interazioni fluido-struttura.</p><h3>Pressioni e AUTO</h3><p>Grafica e solutore condividono la superficie. Un metodo a vortici discreti calcola Δp e integra Σ Δp n A: lift e drag derivano dalle medesime celle della mappa, con correzioni di separazione, attrito e resistenza indotta. Le scie mostrano qualitativamente la separazione; non risolvono la turbolenza tridimensionale. È flusso potenziale a sezioni con correzioni empiriche. Un richiamo elastico progressivo fra 4 e 30 nodi sposta il grasso a poppavia se non si recupera la drizza, con domanda al 25% a 8 nodi, 50% a 12, 93% a 20 e 100% a 30. Le forme più piatte e lo svergolamento progressivo diventano utili già intorno a 8 nodi. Una correzione empirica del recupero di pressione dipende da profondità, posizione del grasso e svergolamento: entra nelle stesse pressioni integrate per lift e drag. Sartie, paterazzo e strallo insufficientemente tesi riducono inoltre il sostegno della pressione in funzione del carico, attraverso una correzione graduale delle stesse celle Δp. La mappa, CL, CD e la velocità ne risentono insieme. Questi parametri del tessuto e del sostegno sono empirici, non ricavati dal certificato.</p><div class="formula">R(V) = F<sub>rif</sub> (V / V<sub>polare</sub>)³<br>Efficienza polare = 100 V / V<sub>polare</sub></div><p>AUTO conserva piano velico e dimensioni scelti dall’utente: ottimizza soltanto le manovre integrando le pressioni e penalizzando carico eccessivo, separazione e instabilità. Le manovre disabilitate mantengono il valore corrente e sono escluse dalla ricerca. Per quelle abilitate la ricerca rispetta intervalli minimi di tensione progressivi per drizze e armo: circa 92% a 20 nodi e 100% a 30. Questi intervalli sono ipotesi operative del modello; le scotte restano libere e il 100% della polare non è garantito per qualunque vela o andatura. F<sub>rif</sub> è calibrata sull’inventario originale della barca. Con vele modificate cerca il risultato ottenibile: il 100% non viene imposto al display. Si tratta di un ottimo numerico trovato nel modello calibrato, non di una nuova previsione VPP certificata.</p>${modelAppendixHTML()}<button class="dialog-action export-button" id="exportData"><svg><use href="#i-download"/></svg> Scarica dati della sessione · CSV</button><a class="source-download" href="./vento-sorgenti.zip" download>Scarica codice e dati · ZIP ↗</a>`);$('#exportData').addEventListener('click',exportCSV);}
$('#guideButton').addEventListener('click',()=>windows.toggleInfo('guide',guide));$('#aboutButton').addEventListener('click',()=>windows.toggleInfo('about',modelInfo));$('#creditsButton').addEventListener('click',()=>windows.toggleInfo('credits',credits));
function exportCSV(){const data=records.length?records:[currentRecord()];const headers=['barca_id','barca_nome','tempo_s','vento_reale_kn','TWA_deg','velocita_kn','target_polare_kn','efficienza_polare_percent','vento_apparente_kn','AWA_deg','vela_prua','LP_J_stimato_percent','gennaker_m2','spinnaker_m2','randa_issata','area_m2','CL','CD','lift_N','drag_N','efficienza_percent','sbandamento_deg'];const csv='\uFEFF'+headers.join(';')+'\n'+data.map(r=>r.map(v=>typeof v==='number'?v.toFixed(3).replace('.',','):'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='vento-sessione.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Dati della sessione esportati.');}
function currentRecord(){return[boatProfile(state).id,boatProfile(state).name,elapsed,state.windSpeed,state.windAngle,speed,metric.polarTarget,metric.polarEfficiency,metric.aws,metric.awa,state.foresail,headsailInfo(state).percent,selectedArea('gennaker',state),selectedArea('spinnaker',state),state.main?1:0,metric.area,metric.cl,metric.cd,metric.lift,metric.drag,metric.efficiency,metric.heel];}
document.addEventListener('keydown',e=>{if(e.key==='Escape')windows.closeTop(()=>closeDirectControl(true));});
function setFold(panelId,buttonId,minimized){const panel=$('#'+panelId),button=$('#'+buttonId);panel.classList.toggle('minimized',minimized);button.setAttribute('aria-expanded',!minimized);const name={windPanel:'condizioni del vento',telemetry:'dati di navigazione',pressureLegend:'legenda pressione',shapeReadout:'dati della forma',planSection:'piano velico'}[panelId];button.setAttribute('aria-label',`${minimized?'Espandi':'Minimizza'} ${name}`);const body=panel.querySelector('.wind-body,.telemetry-body,.plan-body');if(body)body.inert=minimized;}
for(const [panelId,buttonId] of [['windPanel','windFold'],['telemetry','telemetryFold'],['pressureLegend','pressureFold'],['shapeReadout','shapeFold']])$('#'+buttonId).addEventListener('click',()=>setFold(panelId,buttonId,!$('#'+panelId).classList.contains('minimized')));
function profileValues(type){return shapeSummary(type,scene?.visualState||state);}
function shapeCard(type){const p=profileValues(type),before=shapeComparison?.before[type],delta=(key,unit)=>before?` <small class="shape-delta">${p[key]-before[key]>=0?'+':''}${fmt(p[key]-before[key],1)}${unit}</small>`:'';return `<strong>${names[type]}</strong><div class="profile-numbers"><span>Profondità<b>${fmt(p.camber,1)}%${delta('camber','%')}</b></span><span>Grasso a<b>${fmt(p.draft,1)}%${delta('draft','%')}</b></span><span>Svergolamento<b>${fmt(p.twist,1)}°${delta('twist','°')}</b></span></div><small>Sezione al 40% · svergolamento 10–90%</small>`;}
function renderDirectShape(){if(!selectedControlId)return;const cat=selectedControlId.split('.')[0],types=cat==='rig'?[...(state.main?['main']:[]),...(state.foresail!=='none'?[state.foresail]:[])]:[cat];$('#directShapeData').innerHTML=types.map(shapeCard).join('');}
function updateProfileOverlays(){for(const [id,type,active] of [['main','main',state.main],['fore',state.foresail,state.foresail!=='none']]){const el=$('#profile-'+id),enabled=active&&!!state.sailOverlays?.[type];el.classList.toggle('hidden',!enabled);if(enabled)el.querySelector('.profile-content').innerHTML=shapeCard(type);}}
$('#profileOverlayToggle').addEventListener('change',e=>{state.sailOverlays??={};state.sailOverlays[controlTab]=e.target.checked;updateProfileOverlays();});$$('[data-close-profile]').forEach(button=>button.addEventListener('click',()=>{const type=button.dataset.closeProfile==='main'?'main':state.foresail;state.sailOverlays??={};state.sailOverlays[type]=false;$('#profileOverlayToggle').checked=!!state.sailOverlays[controlTab];updateProfileOverlays();}));
function updateInspector(){const sheetInfo=$('#sheetLoadInfo');sheetInfo.classList.toggle('hidden',controlTab==='main');if(controlTab==='genoa'){const lead=genoaLeadGeometry(state);sheetInfo.textContent=`Vento app. ${fmt(lead.aws)} kn · ${fmt(Math.abs(lead.awa),0)}° · tiro stimato ${fmt(lead.sheetTension/1000,2)} kN · scotta ${fmt(lead.downAngle,0)}°${lead.contactLimited?' · limite sartie/crocette':''}`;sheetInfo.title='Equilibrio ridotto fra vento, tiro verso il rinvio e peso del tessuto. Il punto più vicino dipende da taglio e posizione del carrello; non è sempre sopra il carrello.';}if(controlTab==='spinnaker'||controlTab==='gennaker'){const travel=flyingSheetTravel(controlTab,state);sheetInfo.textContent=(controlTab==='spinnaker'?`Varea ${fmt(spinPoleRig(state).tip[1]*boatScale(state),2)} m · dislivello bugne ${fmt(Math.abs(sailPoint('spinnaker',0,0,state)[1]-sailPoint('spinnaker',0,1,state)[1])*boatScale(state),2)} m · `:'')+(travel.contactLimited?'Corsa della scotta limitata dallo strallo':'Scotta: tutta la corsa utile disponibile');sheetInfo.title='La superficie curva resta davanti allo strallo nei punti di attraversamento. Le misure delle ralinghe, della base e della corda media sono conservate.';}const type=controlTab,shape=shapeSummary(type,state),rig=shapeSummary('main',state);$('#shapeTitle').textContent='FORMA '+(type==='main'?'DELLA RANDA':type==='genoa'?'DEL GENOA':type==='spinnaker'?'DELLO SPINNAKER':'DEL GENNAKER');if(type==='main'&&shape.mainLimit<shape.requestedAngle-.5)$('#controlEffect').textContent=`Apertura limitata dal contatto con le sartie: ${fmt(shape.mainLimit)}° al boma.`;$('#shapeValues').innerHTML=`<span>Profondità<b>${fmt(shape.camber)}%</b></span><span>Grasso a<b>${fmt(shape.draft,0)}% corda</b></span><span>Svergolamento<b>${fmt(shape.twist)}°</b></span>`;$('#rigShapeValues').innerHTML=`<span>Flessione laterale<b>${fmt(rig.mastDeflection,2)} m</b></span><span>Catenaria strallo<b>${fmt(rig.forestaySag,2)} m</b></span><span>Precurvatura<b>${fmt(rig.prebend,2)} m</b></span>`;}
setFold('shapeReadout','shapeFold',true);setFold('telemetry','telemetryFold',false);setFold('windPanel','windFold',false);
function positionDirectControl(){windows.anchor($('#directControl'));}
function syncDirectControl(){if(!selectedControlId)return;$('#directControlAuto').dataset.autoControl=selectedControlId;syncSingleAutoButtons();renderDirectShape();const [category,key]=selectedControlId.split('.'),p=controlSpec(category,key),value=controlToValue(category,key,state.controls[category][key]);const enabled=controlEnabled(state,category,key);if(category==='genoa'&&key==='barber')$('#directControlHelp').textContent=p.outOnly?'LP/J oltre 105%: barber solo sul carrello o verso l’esterno.':CONTROL_DEFS.genoa.find(d=>d[0]==='barber')[4];$('#directControlEnabled').checked=enabled;$('#directControlEnabledStatus').textContent=enabled?'Regolabile':'Fissa · esclusa da AUTO';for(const id of ['directControlRange','directControlNumber','directControlCenter','directControlDecrease','directControlIncrease'])$('#'+id).disabled=!enabled;const range=$('#directControlRange'),number=$('#directControlNumber');for(const el of [range,number]){el.min=p.min;el.max=p.max;el.step=p.step;if(el!==document.activeElement||el.type==='range')el.value=p.position?value.toFixed(3):value;el.setAttribute('aria-valuetext',controlPositionDescription(category,key,state.controls[category][key]));}styleRange(range);$('#directControlValue').textContent=formatControlValue(category,key,state.controls[category][key]);$('#directControlUnit').textContent=p.unit;$('#directControlPosition').textContent=category==='genoa'&&key==='sheet'?`${fmt(genoaLeadGeometry(state).sheetTension/1000,2)} kN stimati · tiro verso il rinvio · ${fmt(genoaLeadGeometry(state).downAngle,0)}° dall’orizzontale`:controlPositionDescription(category,key,state.controls[category][key]);$('#directControlCenter').classList.toggle('hidden',!p.centered);$('#directControlPrecision').textContent=key==='sheet'?'0% libera · 100% fine corsa utile · progressione proporzionale':p.position?`Passo 1 mm · corsa ${(p.max-p.min).toLocaleString(getLocale(),{minimumFractionDigits:2,maximumFractionDigits:2})} m`:p.centered?(p.outOnly?'0 = sul carrello · + verso esterno · LP/J oltre 105%':'0 = sul carrello · − verso albero · + verso esterno'):'Passo 1% · modifica la tensione relativa';$('#directControlMin').textContent=p.low||CONTROL_DEFS[category].find(d=>d[0]===key)[2];$('#directControlMax').textContent=p.high||CONTROL_DEFS[category].find(d=>d[0]===key)[3];}
function openDirectControl(selection){if(!selection?.id){closeDirectControl();return;}if(selectedControlId!==selection.id)shapeComparison=null;const [category,key]=selection.id.split('.'),def=CONTROL_DEFS[category]?.find(d=>d[0]===key);if(!def)return;selectedControlId=selection.id;$('#directControl').style.setProperty('--rope-colour',CONTROL_COLORS[selection.id]);$('#directControlName').textContent=def[1];$('#directControlGroup').textContent=category==='rig'?'MANOVRE FISSE':names[category].toUpperCase();$('#directControlHelp').textContent=category==='genoa'&&key==='barber'&&!headsailInhaulAllowed(state)?'LP/J oltre 105%: barber solo sul carrello o verso l’esterno.':def[4];$('#directControl').classList.remove('hidden');scene?.setSelectedControl(selection.id);syncDirectControl();positionDirectControl(selection);(controlEnabled(state,category,key)?$('#directControlRange'):$('#directControlEnabled')).focus({preventScroll:true});}
function closeDirectControl(returnFocus=false){selectedControlId=null;$('#directControl').classList.add('hidden');scene?.setSelectedControl(null);if(returnFocus)$('#oceanCanvas').focus({preventScroll:true});}
function showRigHover(hit){const el=$('#rigHover');if(!hit){el.classList.add('hidden');return;}const [category,key]=hit.id.split('.'),def=CONTROL_DEFS[category]?.find(d=>d[0]===key);if(!def)return;const r=$('#scene').getBoundingClientRect();el.textContent=def[1];el.style.setProperty('--rope-colour',CONTROL_COLORS[hit.id]);el.style.left=`${clamp(hit.clientX-r.left+12,8,r.width-155)}px`;el.style.top=`${clamp(hit.clientY-r.top-30,8,r.height-45)}px`;el.classList.remove('hidden');}
$('#oceanCanvas').addEventListener('sailing-control-selected',e=>openDirectControl(e.detail));$('#directControlClose').addEventListener('click',()=>closeDirectControl(true));
for(const id of ['directControlRange','directControlNumber'])$('#'+id).addEventListener('input',e=>{if(!selectedControlId)return;const [category,key]=selectedControlId.split('.');applyControlValue(category,key,e.target.value);});
$('#directControlEnabled').addEventListener('change',e=>{if(selectedControlId)changeControlEnabled(selectedControlId,e.target.checked);});
$('#directControlAuto').addEventListener('click',()=>{if(selectedControlId)autoSingleControl(selectedControlId);});
$('#directControlCenter').addEventListener('click',()=>{if(selectedControlId==='genoa.barber')applyControlValue('genoa','barber',0);});
$('#directControlNumber').addEventListener('blur',()=>{if(selectedControlId){const [category,key]=selectedControlId.split('.'),p=controlSpec(category,key);$('#directControlNumber').value=controlToValue(category,key,state.controls[category][key]).toFixed(p.position?3:0);}});
for(const [id,direction] of [['directControlDecrease',-1],['directControlIncrease',1]])$('#'+id).addEventListener('click',()=>{if(!selectedControlId)return;const [category,key]=selectedControlId.split('.'),p=controlSpec(category,key),value=controlToValue(category,key,state.controls[category][key]);applyControlValue(category,key,value+p.step*direction);});
document.addEventListener('vento-languagechange',()=>{if(dialog.hasAttribute('open')&&dialog.dataset.panelOwner==='guide')guide();else if(dialog.hasAttribute('open')&&dialog.dataset.panelOwner==='credits')credits();else if(dialog.hasAttribute('open')&&dialog.dataset.panelOwner==='about')modelInfo();updatePlan();renderControls();renderSailMeasures();syncWindInputs();syncAuto();syncPause();updateUI();if($('#certificateFilter'))$('#certificateFilter').dispatchEvent(new Event('input'));if($('#boatSearch'))$('#boatSearch').dispatchEvent(new Event('input'));});
panelTab('plan');renderControls();updatePlan();renderSailMeasures();syncWindInputs();syncAuto();updateUI();drawChart();
initI18n();
try{const {SailingScene}=await import('./scene.js');scene=new SailingScene($('#oceanCanvas'),()=>state,()=>metric,selection=>$('#oceanCanvas').dispatchEvent(new CustomEvent('sailing-control-selected',{detail:selection})),showRigHover);}catch(error){$('#webglMessage').classList.remove('hidden');console.error('Vista 3D non disponibile:',error);}
let physicsTime=0;
function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!state.paused){elapsed+=dt;speed=lerp(speed,metric.targetSpeed,1-Math.exp(-dt/3.4));state.boatSpeed=speed;advanceJibDynamics(state,dt);keepAutoCarBehindClew();physicsTime+=dt;if(physicsTime>(Math.abs(state.jibAngularVelocity||0)>.08?.05:.16)){state.boatSpeed=speed;metric=evaluate(state,speed);physicsTime=0;}state.boatSpeed=speed;metric.speed=speed;metric.polarEfficiency=metric.polarTarget>.01?speed/metric.polarTarget*100:0;chartTime+=dt;if(chartTime>=1){chartTime-=1;history.push(speed);history.shift();records.push(currentRecord());if(records.length>7200)records.shift();drawChart();}}
 scene?.render(dt,metric);audio.update(state.windSpeed,elapsed);uiTime+=dt;if(uiTime>.18){updateUI();uiTime=0;}requestAnimationFrame(frame);}
requestAnimationFrame(frame);
initialReferenceTimer=setTimeout(()=>requestOptimization(state.auto),150);
// Read-only diagnostics for accessibility / integration checks; no external services or persistence.
window.vento={getState:()=>structuredClone(state),getMetrics:()=>structuredClone(metric)};
